# 补齐两处文案：
# 1）裸 key「打开模型文件夹」：被用作 accessibilityLabel，源码已抽取但目录里没有任何译文；
# 2）隐私说明（PrivacyConsentView / SettingsView.PrivacyPolicyDetailView）修订后的新源文：
#    移除 iOS 表述（工程已仅支持 macOS）、补充月份归档 / PII 脱敏 / 声纹 / 卸载后保留范围，
#    并让两处视图共用同一份「数据存储 / 数据传输 / 用户权利」源文以消除文案漂移。
#
# 设计要点与既有 Scripts/add_*l10n*.py 一致：
# - 源语言 zh-Hans 取 key 本身（目录 sourceLanguage 即 zh-Hans）；
# - 每个 key 都校验 20 种目标语言齐全且与源文占位符一致；
# - 只新增/覆盖本次列出的 key，不动其它条目。
import json
import re

CATALOG = 'Memonta/Resources/Localizable.xcstrings'
LANGS = ['zh-Hant', 'en', 'ja', 'ko', 'fr', 'de', 'es', 'it', 'pt', 'ru',
         'ar', 'hi', 'th', 'vi', 'id', 'tr', 'nl', 'pl', 'uk', 'sv']

PLACEHOLDER = re.compile(
    r'%(?:\d+\$)?[-+ #0]*\d*(?:\.\d+)?(?:hh|h|ll|l|L|q|z|j|t)?[@dfsl]')

T = {}


def placeholders(text):
    """占位符种类与数量（把 %1$@ 归一为 %@）。"""
    return sorted('%' + m[-1] for m in PLACEHOLDER.findall(text))


def add(key, vals):
    assert len(vals) == len(LANGS), key
    expected = placeholders(key)
    for lang, val in zip(LANGS, vals):
        assert placeholders(val) == expected, f'占位符不一致 {key[:40]} / {lang}'
    T[key] = vals


